import React, { useState } from 'react';
import { Tabs, TabItem, Dropdown } from '@salutejs/sdds-finai';
export function App() {
    const items = Array(8).fill(0);
    const [index, setIndex] = useState(0);
    const maxItemQuantity = 3;
    const visibleItems = items.slice(0, maxItemQuantity);
    const otherItems = items.slice(maxItemQuantity);
    const dropdownItems = otherItems.map((_, i) => {
        const itemIndex = maxItemQuantity + i;
        return {
            label: `Label${itemIndex + 1}`,
            value: itemIndex,
        };
    });
    return (
        <div style={{ height: '15rem', alignItems: 'flex-start' }}>
            <Tabs clip="showAll" view="divider" size="xs">
                {visibleItems.map((_, i) => (
                    <TabItem
                        key={`item:${i}`}
                        view="divider"
                        selected={i === index}
                        onClick={() => setIndex(i)}
                        tabIndex={0}
                        size="xs"
                    >
                        {`Label${i + 1}`}
                    </TabItem>
                ))}
                {dropdownItems.length > 0 && (
                    <div style={{ marginLeft: '1.75rem' }}>
                        <Dropdown size="xs" items={dropdownItems} onItemSelect={(item) => setIndex(item.value)}>
                            <TabItem key="item:ShowAll" view="divider" tabIndex={0} size="xs">
                                ShowAll
                            </TabItem>
                        </Dropdown>
                    </div>
                )}
            </Tabs>
        </div>
    );
}

import React, { useState } from 'react';
import { Tabs, TabItem, Dropdown } from '@salutejs/sdds-finai';
export function App() {
    const items = Array(8).fill(0);
    const maxItemQuantity = 3;
    const [order, setOrder] = useState(items.map((_, i) => i));
    const [selected, setSelected] = useState(order[0]);
    const visibleItems = order.slice(0, maxItemQuantity);
    const otherItems = order.slice(maxItemQuantity);
    const dropdownItems = otherItems.map((itemIndex) => ({
        label: `Label${itemIndex + 1}`,
        value: itemIndex,
    }));
    const onSelectDropdownItem = (item) => {
        setOrder((prevOrder) => {
            const newOrder = prevOrder.filter((itemIndex) => itemIndex !== item.value);
            newOrder.splice(maxItemQuantity - 1, 0, item.value);
            return newOrder;
        });
        setSelected(item.value);
    };
    return (
        <div style={{ height: '15rem', alignItems: 'flex-start' }}>
            <Tabs clip="showAll" view="divider" size="xs">
                {visibleItems.map((itemIndex) => (
                    <TabItem
                        key={`item:${itemIndex}`}
                        view="divider"
                        selected={itemIndex === selected}
                        onClick={() => setSelected(itemIndex)}
                        tabIndex={0}
                        size="xs"
                    >
                        {`Label${itemIndex + 1}`}
                    </TabItem>
                ))}
                {dropdownItems.length > 0 && (
                    <div style={{ marginLeft: '1.75rem' }}>
                        <Dropdown size="xs" items={dropdownItems} onItemSelect={onSelectDropdownItem}>
                            <TabItem key="item:ShowAll" view="divider" tabIndex={0} size="xs">
                                ShowAll
                            </TabItem>
                        </Dropdown>
                    </div>
                )}
            </Tabs>
        </div>
    );
}

import React, { useState } from 'react';
import { Tabs, TabItem } from '@salutejs/sdds-finai';
import { IconClock } from '@salutejs/plasma-icons';
export function App() {
    const items = Array(4).fill(0);
    const [horizontalIndex, setHorizontalIndex] = useState(0);
    const [verticalIndex, setVerticalIndex] = useState(0);
    return (
        <div style={{ display: "flex", flexDirection: "column", gap: "50px"}}>
            <div>
                <Tabs view="divider" stretch size="xs" index={horizontalIndex}>
                    {items.map((_, i) => (
                        <TabItem
                            view="divider"
                            key={`item:${i}`}
                            size="xs"
                            itemIndex={i}
                            onIndexChange={(i) => setHorizontalIndex(i)}
                            selected={i === horizontalIndex}
                            tabIndex={0}
                            contentLeft={<IconClock size="xs" color="inherit" />}
                            onClick={() => setHorizontalIndex(i)}
                        >
                            {`Label${i + 1}`}
                        </TabItem>
                    ))}
                </Tabs>
            </div>
            <div>
                <Tabs orientation="vertical" view="divider" size="xs" index={verticalIndex}>
                    {items.map((_, i) => (
                        <TabItem
                            orientation="vertical"
                            view="divider"
                            key={`item:${i}`}
                            size="xs"
                            itemIndex={i}
                            onIndexChange={(i) => setVerticalIndex(i)}
                            selected={i === verticalIndex}
                            tabIndex={0}
                            contentLeft={<IconClock size="xs" color="inherit" />}
                            onClick={() => setVerticalIndex(i)}
                        >
                            {`Label${i + 1}`}
                        </TabItem>
                    ))}
                </Tabs>
            </div>
        </div>
    );
}
